def expand_month(abbr):
    months = {"Jan": "January", "Feb": "February", "Mar": "March", "Apr": "April",
               "May": "May", "Jun": "June", "Jul": "July", "Aug": "August",
               "Sep": "September", "Oct": "October", "Nov": "November", "Dec": "December"}
    return months.get(abbr.capitalize(), abbr)

def format_ordinal_date(day, month_name):
    a = abs(day)
    if 11 <= a % 100 <= 13:
        suf = 'th'
    else:
        suf = {1: 'st', 2: 'nd', 3: 'rd'}.get(a % 10, 'th')
    return f"{day}{suf} of {month_name}"

def format_fraction_as_mixed(numerator, denominator):
    import math
    whole = numerator // denominator
    rem = numerator % denominator
    if rem == 0:
        return str(whole)
    g = math.gcd(rem, denominator)
    rem //= g
    denominator //= g
    if whole == 0:
        return f"{rem}/{denominator}"
    return f"{whole} {rem}/{denominator}"

def left_truncate_path(path, maxlen):
    if len(path) <= maxlen:
        return path
    keep = maxlen - 3
    if keep <= 0:
        return path[-maxlen:]
    return '...' + path[-keep:]

def camel_case_join(words):
    if not words:
        return ""
    return words[0].lower() + ''.join(w.capitalize() for w in words[1:])

def wrap_indent_block(text, width, indent):
    words = text.split()
    lines = []
    current = ''
    for w in words:
        if not current:
            current = w
        elif len(current) + 1 + len(w) <= width:
            current += ' ' + w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    prefix = ' ' * indent
    return '\n'.join(prefix + line for line in lines)
